import json

# Let me create the proper Python file that implements the transform function
# and test it

def transform(grid):
    """
    Transform grid based on observed patterns from demos.

    Pattern: 
    - Identify gap columns in horizontal 8-line rows  
    - The "hero" column is the middle gap column
    - A full horizontal band of 2s at the "special" row (where 2 is) from col 0 to max_gap-1
    - A full vertical line of 2s at the hero column (not overwriting 8-lines)
    """
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    output = [row[:] for row in grid]

    # Find special row (where 2 is)
    special_row = None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                special_row = r
                break
        if special_row is not None:
            break

    if special_row is None:
        return grid

    # Find horizontal line rows and their gaps
    horizontal_lines = []  # list of (row_num, set of gap_cols)
    for r in range(rows):
        if any(grid[r][c] == 8 for c in range(cols)):
            gaps = set(c for c in range(cols) if grid[r][c] != 8)
            if gaps:
                horizontal_lines.append((r, gaps))

    if not horizontal_lines:
        return grid

    # All gap columns
    all_gap_cols = set()
    for r, gaps in horizontal_lines:
        all_gap_cols.update(gaps)
    gap_cols = sorted(all_gap_cols)

    if not gap_cols:
        return grid

    # Hero = middle gap column
    hero_col = gap_cols[len(gap_cols) // 2]
    max_gap = gap_cols[-1]  # last gap column

    # Horizontal band at special_row: cols 0 to max_gap-1
    for c in range(max_gap):
        if output[special_row][c] not in [8]:  # Don't overwrite 8s
            output[special_row][c] = 2

    # Fill 2s at all gap column positions in horizontal line rows
    for r, gaps in horizontal_lines:
        for gap_col in gaps:
            output[r][gap_col] = 2

    # Vertical band at hero_col (for rows that are NOT horizontal line rows with hero gap)
    for r in range(rows):
        is_horizontal_line = any(hl[0] == r for hl in horizontal_lines)
        if is_horizontal_line:
            hero_gap_in_row = hero_col in horizontal_lines[r][1]
            if not hero_gap_in_row:
                output[r][hero_col] = 2

    return output

